import { useFocusEffect } from '@react-navigation/native';
import { useCallback, useState } from 'react';
import { ActivityIndicator, Pressable, StyleSheet, Text, View } from 'react-native';

import ExpoBenchHealth from '../modules/expo-bench-health/src/ExpoBenchHealthModule';
import { DailyStepEntry, HealthAuthorizationStatus } from '../modules/expo-bench-health/src/ExpoBenchHealth.types';

const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

function formatDayLabel(ms: number): string {
  const date = new Date(ms);
  return `${WEEKDAYS[date.getDay()]} ${MONTHS[date.getMonth()]} ${date.getDate()}`;
}

function formatSteps(count: number): string {
  return count.toLocaleString('en-US');
}

function startOfTodayMs(): number {
  const date = new Date();
  date.setHours(0, 0, 0, 0);
  return date.getTime();
}

function statusLineText(status: HealthAuthorizationStatus): string {
  switch (status) {
    case 'sharingAuthorized':
      return 'Health access: granted';
    case 'sharingDenied':
      return 'Health access: denied';
    default:
      return 'Health access: not requested';
  }
}

function errorText(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

export default function HealthScreen() {
  const [authStatus, setAuthStatus] = useState<HealthAuthorizationStatus>('notDetermined');
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [days, setDays] = useState<DailyStepEntry[] | null>(null);
  const [isLoadingDays, setIsLoadingDays] = useState(false);

  const loadDays = useCallback(async () => {
    setIsLoadingDays(true);
    try {
      const result = await ExpoBenchHealth.getDailySteps();
      setDays(result);
    } catch (error) {
      setErrorMessage(errorText(error));
    } finally {
      setIsLoadingDays(false);
    }
  }, []);

  useFocusEffect(
    useCallback(() => {
      const status = ExpoBenchHealth.getAuthorizationStatus();
      setAuthStatus(status);
      if (status === 'sharingAuthorized') {
        loadDays();
      }
    }, [loadDays])
  );

  const handleRequestAccess = async () => {
    setErrorMessage(null);
    try {
      const status = await ExpoBenchHealth.requestAuthorization();
      setAuthStatus(status);
      if (status === 'sharingAuthorized') {
        loadDays();
      }
    } catch (error) {
      setErrorMessage(errorText(error));
    }
  };

  const handleLogSteps = async () => {
    setErrorMessage(null);
    try {
      await ExpoBenchHealth.saveSteps(500);
      await loadDays();
    } catch (error) {
      setErrorMessage(errorText(error));
    }
  };

  const canLog = authStatus === 'sharingAuthorized';
  const today = startOfTodayMs();

  return (
    <View style={styles.container}>
      <Text style={styles.status}>{errorMessage ?? statusLineText(authStatus)}</Text>

      <Pressable style={styles.button} onPress={handleRequestAccess}>
        <Text style={styles.buttonText}>Request Access</Text>
      </Pressable>
      <Pressable
        style={[styles.button, !canLog && styles.buttonDisabled]}
        disabled={!canLog}
        onPress={handleLogSteps}>
        <Text style={[styles.buttonText, !canLog && styles.buttonTextDisabled]}>Log 500 Steps</Text>
      </Pressable>

      <Text style={styles.sectionHeader}>Last 7 Days</Text>
      {authStatus !== 'sharingAuthorized' ? (
        <View style={styles.emptyState}>
          <Text style={styles.emptyStateText}>Health access needed</Text>
        </View>
      ) : days === null && isLoadingDays ? (
        <ActivityIndicator style={styles.emptyState} />
      ) : (
        (days ?? []).slice().reverse().map((day) => {
          const isToday = day.startOfDayMs === today;
          return (
            <View key={day.startOfDayMs} style={styles.row}>
              <Text style={[styles.rowText, isToday && styles.rowTextToday]}>
                {formatDayLabel(day.startOfDayMs)} — {formatSteps(day.steps)} steps
                {isToday ? ' (today)' : ''}
              </Text>
            </View>
          );
        })
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#fff',
    padding: 24,
  },
  status: {
    fontSize: 16,
    color: '#333',
    marginBottom: 24,
  },
  button: {
    backgroundColor: '#007AFF',
    borderRadius: 12,
    paddingVertical: 16,
    alignItems: 'center',
    marginBottom: 16,
  },
  buttonDisabled: {
    backgroundColor: '#ccc',
  },
  buttonText: {
    color: '#fff',
    fontSize: 17,
    fontWeight: '600',
  },
  buttonTextDisabled: {
    color: '#888',
  },
  sectionHeader: {
    fontSize: 20,
    fontWeight: '700',
    marginTop: 24,
    marginBottom: 12,
  },
  emptyState: {
    alignItems: 'center',
    paddingVertical: 32,
  },
  emptyStateText: {
    fontSize: 16,
    color: '#999',
  },
  row: {
    paddingVertical: 10,
    borderBottomWidth: StyleSheet.hairlineWidth,
    borderBottomColor: '#e0e0e0',
  },
  rowText: {
    fontSize: 16,
    color: '#333',
  },
  rowTextToday: {
    fontWeight: '700',
    color: '#007AFF',
  },
});

